from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='La muerte de Carlos II en 1700 sin descendencia abrió una guerra europea por el control del Imperio español y terminó con la instauración de la dinastía Borbón y con la abolición de las leyes propias de la Corona de Aragón. Este capítulo explica quiénes se enfrentaron, qué se pactó en Utrecht, qué supusieron los decretos de Nueva Planta y cómo se relacionan con la unión dinástica estudiada en el primer capítulo.',
        quotes=[Q('es_sucesion','La guerra dejó como principal consecuencia la instauración de la casa de Borbón en el trono de España'), Q('en_nueva_planta','The decrees put an end to the existence of the realms of the Crown of Aragon')]))
    P.append(dict(text='El candidato oficial, designado por Carlos II poco antes de morir, era Felipe de Anjou, nieto de Luis XIV de Francia ({{fig:felipe-v}}), que fue proclamado rey de España el 16 de noviembre de 1700. Su rival era el archiduque Carlos de Austria, hijo menor del emperador Leopoldo I, que contaba con el apoyo de la Gran Alianza, formada, entre otros, por Austria, las Provincias Unidas y Gran Bretaña. La posibilidad de que Francia o Austria adquiriese el conjunto del imperio amenazaba el equilibrio de poder europeo, y por eso la proclamación de Felipe condujo a la guerra.',
        quotes=[Q('es_sucesion','Su heredero oficial era Felipe de Anjou, nieto de Luis XIV de Francia'), Q('es_sucesion','contaba con el apoyo de la Gran Alianza, cuyos principales miembros incluían a Austria, las Provincias Unidas y Gran Bretaña'), Q('en_sucesion','Philip\'s proclamation as king on 16 November 1700 triggered war'), Q('en_carlos2','Charles made the latter his heir shortly before dying in November 1700')]))
    P.append(dict(text='Las fuentes datan la guerra de maneras distintas. Una dice que duró de 1701 hasta la firma del Tratado de Utrecht en 1714; en otro punto, la misma fuente sitúa la Paz de Utrecht en 1713, seguida de los tratados de Rastatt y Baden en 1714. Otra de las fuentes habla de la guerra de sucesión española como de 1701 a 1715. Las tres fechas pueden reconciliarse: Utrecht fue en 1713, Rastatt y Baden en 1714, y en España los últimos focos de resistencia austracista se extinguieron en 1714 con Barcelona y en 1715 con Mallorca.',
        quotes=[Q('es_sucesion','duró desde 1701 hasta la firma del Tratado de Utrecht en 1714'), Q('es_sucesion','su retirada condujo a la Paz de Utrecht en 1713, seguida de los tratados de Rastatt y Baden en 1714'), Q('es_nueva_planta','guerra de sucesión española (1701-1715)'), Q('es_sucesion','1714, con la capitulación de Barcelona, y 1715, con la rendición de Mallorca ante las fuerzas de Felipe V')]))
    P.append(dict(text='En España la guerra fue también una guerra civil entre borbónicos, con su principal apoyo en Castilla, y austracistas, mayoritarios en Aragón. En 1705 el Pacto de Génova entre representantes catalanes y Gran Bretaña abrió un segundo frente en el nordeste, y Carlos convocó en Barcelona las últimas Cortes Generales de Cataluña. Para 1709, aunque la Gran Alianza había obligado a Francia a ponerse a la defensiva, Felipe ya había consolidado su posición en España.',
        quotes=[Q('es_sucesion','la guerra de sucesión evolucionó hasta convertirse en una guerra civil entre borbónicos, cuyo principal apoyo lo encontraron en Castilla, y austracistas, mayoritarios en Aragón'), Q('en_sucesion','The 1705 Pact of Genoa between Catalan representatives and Britain opened a second front in the north-east'), Q('en_sucesion','By 1709, although the Grand Alliance had forced France onto the defensive, Philip had secured his position in Spain.'), Q('en_sucesion','Charles convened in Barcelona the last General Court of Catalonia')]))
    P.append(dict(text='Un acontecimiento dinástico cambió el cálculo de los aliados: cuando murió el emperador José I en 1711, el archiduque Carlos le sucedió como emperador. Como una unión de España y Austria resultaba tan mal recibida como una con Francia, el nuevo gobierno británico argumentó que no tenía sentido continuar, y el apoyo de Gran Bretaña, cuyos subsidios mantenían a los aliados, se retiró. Esa retirada condujo a la Paz de Utrecht.',
        quotes=[Q('es_sucesion','Cuando el emperador José I murió en 1711, el archiduque Carlos sucedió a su hermano como emperador del Sacro Imperio Romano Germánico'), Q('en_sucesion','the new British government began negotiating their withdrawal from the war'), Q('es_sucesion','A esas alturas, sólo los subsidios británicos mantenían a sus aliados en la guerra')]))
    P.append(dict(text='En Utrecht, Felipe V fue confirmado como rey de España, pero renunció a su derecho y al de sus descendientes al trono francés. España perdió sus posesiones europeas: gran parte de los territorios italianos pasaron a Saboya y a Austria, que obtuvo también los Países Bajos españoles. Gran Bretaña recibió Gibraltar y Menorca y el asiento de negros, con el que podía enviar a la América española un total de 144 000 esclavos durante treinta años. España firmó con Saboya y con Gran Bretaña el 13 de julio de 1713.',
        quotes=[Q('es_sucesion','Felipe fue confirmado como rey de España, pero renunció a su derecho y al de sus descendientes al trono francés.'), Q('es_sucesion','la pérdida de sus posesiones europeas, incluyendo gran parte de sus territorios italianos a favor de Saboya y Austria, junto con los Países Bajos Españoles'), Q('es_utrecht','podía enviar a la América española un total de 144 000 esclavos durante treinta años'), Q('en_utrecht','In Article X, Spain ceded the strategic ports of Gibraltar and Menorca.'), Q('en_utrecht','Spain under Philip V signed separate peace treaties with Savoy and Great Britain at Utrecht on 13 July.')]))
    P.append(dict(text='La guerra dejó a la Monarquía Hispánica sin sus posesiones europeas, aunque permaneció prácticamente intacta fuera de Europa. Gran Bretaña pasó a ocupar el lugar de las Provincias Unidas como principal potencia naval y comercial europea. Francia quedó exhausta económicamente, pero consiguió su objetivo: romper el cerco de los Habsburgo con un Borbón en el trono de España.',
        quotes=[Q('es_sucesion','aunque permaneció prácticamente intacto fuera de Europa'), Q('en_sucesion','Britain retained the key ports of Gibraltar and Menorca and now replaced the Dutch Republic as the leading European naval and commercial power'), Q('en_sucesion','the installation of a Bourbon on the Spanish throne achieved its long-envisioned goal of breaking the Habsburg monarchy\'s encirclement of its borders')]))
    P.append(dict(text='Los decretos de Nueva Planta, promulgados entre 1707 y 1716 por Felipe V ({{fig:sucesion-cronologia}}), abolieron las leyes e instituciones propias del Reino de Valencia y del Reino de Aragón el 29 de junio de 1707, del Reino de Mallorca el 28 de noviembre de 1715 y del Principado de Cataluña el 16 de enero de 1716. Se aplicaron a los territorios de la Corona de Aragón que se habían decantado por el archiduque Carlos y pusieron fin a la estructura compuesta de la Monarquía de los Austrias. Formalmente eran reales cédulas que establecían la nueva planta de las reales audiencias.',
        quotes=[Q('es_nueva_planta','promulgados entre 1707 y 1716 por el rey Felipe V','del Principado de Cataluña el 16 de enero de 1716'), Q('es_nueva_planta','poniendo fin así a la estructura compuesta de la Monarquía Hispánica de los Austrias'), Q('en_nueva_planta','The acts abolishing the charters were promulgated in 1707 in the kingdoms of Valencia and Aragon, in 1715 in the Kingdom of Majorca and in 1716 in the Principality of Catalonia.')]))
    P.append(dict(text='Los efectos fueron de gran alcance. Según una de las fuentes, los decretos crearon un estado español centralizado al abolir las distinciones legales entre castellanos y aragoneses, catalanes, valencianos y mallorquines, suprimieron las instituciones políticas de los territorios, como las Cortes de Aragón, de Cataluña y de Valencia, y eliminaron las fronteras y aranceles internos, salvo en el territorio vasco. Los altos funcionarios pasaron a nombrarse desde Madrid y el castellano se convirtió en la única lengua de gobierno. Navarra y los territorios vascos conservaron sus fueros porque Felipe V renunció a suprimirlos.',
        quotes=[Q('en_nueva_planta','The decrees effectively created a centralized Spanish state and Spanish citizenship by abolishing all legal distinctions between the Castilians and the Aragonese, Catalans, Valencians and Majorcans.'), Q('en_nueva_planta','The decrees erased all internal borders and tariffs except for the Basque territory'), Q('en_nueva_planta','he backed down on his intent to suppress home rule'), Q('es_nueva_planta','Estos decretos también fueron aplicados a la organización jurídica y administrativa de la Corona de Castilla.')]))
    P.append(dict(text='Esta reforma culminó un viejo problema de la monarquía. Hasta 1700 la monarquía de los Austrias había sido un conglomerado dinástico de «Reinos, Estados y Señoríos» unidos según la fórmula aeque principaliter, bajo la cual cada reino conservaba sus propias leyes, fueros y privilegios. La Nueva Planta suprimió ese modelo para los reinos de la Corona de Aragón, y una de las fuentes lo explica por el modelo de Francia: la monarquía de Luis XIV había alcanzado un grado de unidad muy superior, y Felipe V, nacido en Francia, la tomó como modelo de estado centralizado. Es la conclusión del hilo que empezó con la unión dinástica de Isabel y Fernando y que Olivares había intentado reformar sin éxito.',
        quotes=[Q('es_nueva_planta','unidos según la fórmula aeque principaliter, bajo la cual los reinos constituyentes continuaban después de su unión siendo tratados como entidades distintas, de modo que conservaban sus propias leyes, fueros y privilegios'), Q('es_nueva_planta','Esta, durante el reinado de Luis XIV, había alcanzado un grado de unidad muy superior al del resto de las monarquías compuestas europeas'), Q('en_catolicos','Castile and Aragon remained separate kingdoms until the Nueva Planta decrees of 1707–1716'), Q('en_nueva_planta','taking his native France as a model of a centralised state'), Q('es_nueva_planta','La monarquía compuesta de los Austrias y el fracaso de la reforma de Olivares')]))
    P.append(dict(role='definition', text='Decretos de Nueva Planta: conjunto de decretos que Felipe V promulgó entre 1707 y 1716 para abolir las leyes e instituciones propias de los reinos de la Corona de Aragón y establecer en ellos la «nueva planta» de las audiencias, a la manera de Castilla.',
        quotes=[Q('es_nueva_planta','Los Decretos de Nueva Planta son un conjunto de decretos promulgados entre 1707 y 1716 por el rey Felipe V'), Q('en_nueva_planta','were a number of decrees signed between 1707 and 1716 by Philip V')]))
    P.append(dict(role='consejo', text='Cuando una guerra tiene varias fechas de final, distinga entre la paz internacional y la capitulación de los últimos reductos internos. En esta guerra, Utrecht (1713), Rastatt y Baden (1714), Barcelona (1714) y Mallorca (1715) son cuatro finales distintos de un mismo conflicto, y las fuentes pueden tomar uno u otro como cierre.',
        quotes=[Q('es_sucesion','su retirada condujo a la Paz de Utrecht en 1713, seguida de los tratados de Rastatt y Baden en 1714'), Q('en_utrecht','Negotiations at Utrecht dragged on into the next year')]))
    P.append(dict(role='self_check', text='¿Qué pretendían la Gran Alianza y Francia con la sucesión de Carlos II? ¿Qué se concedió a Gran Bretaña en Utrecht? ¿Qué instituciones abolió la Nueva Planta y por qué se dice que puso fin a la monarquía compuesta de los Austrias?',
        quotes=[Q('es_sucesion','Gran Bretaña recibió Gibraltar y Menorca y obtuvo importantes concesiones comerciales en las Américas españolas'), Q('en_nueva_planta','incorporated them into the Crown of Castile')]))
    return P

def _legacy_numeric_problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Los decretos de Nueva Planta se promulgaron para Valencia y Aragón el 29 de junio de 1707 y para Cataluña el 16 de enero de 1716. Entre las dos fechas hay 3123 días. Calcule cuántos años (con una cifra decimal) pasaron entre el primer y el último decreto, tomando 365,25 días por año.',
        expected='8.6', quotes=[Q('es_nueva_planta','del Reino de Valencia y del Reino de Aragón el 29 de junio de 1707','del Principado de Cataluña el 16 de enero de 1716'), Q('en_nueva_planta','a number of decrees signed between 1707 and 1716')],
        method='Diferencia de fechas convertida a años',
        solution=dict(given=[dict(symbol='d',value=3123,unit='dimensionless',meaning='días entre el 29-06-1707 y el 16-01-1716'),dict(symbol='y',value=365.25,unit='dimensionless',meaning='días por año medio')],
          unknown='El número de años entre el primer y el último decreto.',
          model=[dict(name='Años entre decretos',latex='T = d / y',symbolic='d/y')],
          assumptions=['Se cuentan los días de calendario gregoriano.','Se consideran solo los decretos de Valencia, Aragón, Mallorca y Cataluña; la fecha del de Mallorca, 28 de noviembre de 1715, cae dentro del intervalo.'],
          development=['El primer decreto es el de Valencia y Aragón y el último es el de Cataluña, así que el intervalo mide el tiempo que tardó la Corona en completar la reforma.'],
          steps=[dict(text='Años entre decretos',equation='T = 3123 / 365{,}25',expression='3123/365.25',expected=8.5503,unit='dimensionless')],
          result='Pasaron unos 8,6 años entre el primer decreto y el último.',
          interpretation='La reforma no se impuso de golpe: se aplicó territorio a territorio, según se iba ganando la guerra, en un lapso de más de ocho años.',
          limitations=['El cálculo mide fechas de promulgación, no de aplicación efectiva.'],
          mistakes=['Restar solo los años, 1716 - 1707 = 9, que sobrestima el intervalo en cerca de cinco meses.']))]


